// Episode 28 - 8-tap transposed-form FIR, 16-bit signed samples and Q1.15 coefficients (generated by scripts/gen_fir.py).
// x -> xr (A register) -> m_k = h_k * xr (M register) -> p_k = m_k + p_(k+1) (P register); y = p_0.  Three register stages (A, M, P).
module fir8 (input wire clk, input wire signed [15:0] x, output wire signed [34:0] y);
    reg signed [15:0] xr = 0;
    always @(posedge clk) xr <= x;
    wire signed [15:0] h0 = -236;
    wire signed [15:0] h1 = 0;
    wire signed [15:0] h2 = 4426;
    wire signed [15:0] h3 = 12194;
    wire signed [15:0] h4 = 12194;
    wire signed [15:0] h5 = 4426;
    wire signed [15:0] h6 = 0;
    wire signed [15:0] h7 = -236;
    reg signed [31:0] m0 = 0; always @(posedge clk) m0 <= h0 * xr;
    reg signed [31:0] m1 = 0; always @(posedge clk) m1 <= h1 * xr;
    reg signed [31:0] m2 = 0; always @(posedge clk) m2 <= h2 * xr;
    reg signed [31:0] m3 = 0; always @(posedge clk) m3 <= h3 * xr;
    reg signed [31:0] m4 = 0; always @(posedge clk) m4 <= h4 * xr;
    reg signed [31:0] m5 = 0; always @(posedge clk) m5 <= h5 * xr;
    reg signed [31:0] m6 = 0; always @(posedge clk) m6 <= h6 * xr;
    reg signed [31:0] m7 = 0; always @(posedge clk) m7 <= h7 * xr;
    reg signed [34:0] p7 = 0; always @(posedge clk) p7 <= m7;
    reg signed [34:0] p6 = 0; always @(posedge clk) p6 <= m6 + p7;
    reg signed [34:0] p5 = 0; always @(posedge clk) p5 <= m5 + p6;
    reg signed [34:0] p4 = 0; always @(posedge clk) p4 <= m4 + p5;
    reg signed [34:0] p3 = 0; always @(posedge clk) p3 <= m3 + p4;
    reg signed [34:0] p2 = 0; always @(posedge clk) p2 <= m2 + p3;
    reg signed [34:0] p1 = 0; always @(posedge clk) p1 <= m1 + p2;
    reg signed [34:0] p0 = 0; always @(posedge clk) p0 <= m0 + p1;
    assign y = p0;
endmodule
